/* vml_compat.h —— 把「位置难兼容」的扩展关键字按**透明的空白**抹掉
 *
 * ## 为什么用空宏，而不是在解析器里认
 *
 * 这些关键字来自 GCC / MSVC / Borland，我们**不用它们做任何事**。但它们能出现在
 * **十来种语法位置**（形参、声明前、函数定义前、结构体成员后、`typedef` 里……），
 * 逐个位置去认等于把**同一条规则实现十来遍** —— 而"同一规则两处实现必然漂移"
 * 是本仓头号坑。用空宏一处抹掉，解析器一行都不用改。
 *
 * 真实工具链也是这么办的：GCC 的 `<sys/cdefs.h>` 就用空宏把别家编译器的
 * `__attribute__` 之类抹掉，好让 libc 头能在各家编译器上通用。
 *
 * ## 为什么放在头文件里、且由 stdio.h / stdlib.h 带进来
 *
 * ① 真实程序**几乎都会包含 stdio.h 或 stdlib.h**；
 * ② 本前端对**源文件里没有 `#` 的文件会整段跳过预处理**（`CCompiler.hasPreprocessor`），
 *    宏就无从生效 —— 依赖"程序总会包含 std"这条包含关系，比给每个文件注入一遍省事得多。
 *
 * ## 判据：**丢掉不改变可观察行为**
 *
 * ⚠ 直接操作汇编 / 直接操作内存的那一族**故意不在这里**：
 *   `_AX`/`_BX`（寄存器伪变量）、`asm`/`__asm__`、`__emit__`、显存直写（`0xB8000`/`0xA0000`）、
 *   `bios.h`/`int86`、`interrupt`。它们**恰恰就是**那个可观察行为 ——
 *   抹掉只会让这类程序**看起来能跑、实际静默编错**，比直接编不过更糟。
 *   按定案它们的待遇是「**不支持，或修改掉才能支持**」，见 docs/老程序兼容性.md 的 C 档。
 */
#ifndef _VML_COMPAT_H
#define _VML_COMPAT_H

/* ── GCC / Clang ────────────────────────────────────────────── */

/* 属性注解：能出现在十来种语法位置，是本文件存在的主要理由 */
#define __attribute__(x)

/* "接下来用的是扩展语法"前缀，纯声明性 */
#define __extension__

/* 内联**提示**，不改变可观察行为 */
#define __inline__
#define __inline

/* 别名限定符：只允许编译器假设指针之间不重叠；我们不做别名优化 */
#define __restrict
#define __restrict__

/* ── MSVC ───────────────────────────────────────────────────── */
#define __declspec(x)

/* ── C99 标准关键字（本前端不认，当透明的抹掉）───────────────── */
#define restrict

/* ── Borland / Turbo C ──────────────────────────────────────── */

/* 内存模型限定符：在平坦地址空间下本就无意义，抹掉是**正确**的（不是将就）
 * —— 它们当年只是告诉 16 位编译器该用远指针还是近指针 */
#define far
#define near
#define huge

#endif /* _VML_COMPAT_H */
